var prefabs=new[]{ui.ArcherTowerPrefab,ui.MegicTowerPrefab,ui.MortarTowerPrefab,ui.UnitTowerPrefab};
foreach(var prefab in prefabs){
 EconomyManager.Gold=10000;
 var tower=UnityEngine.Object.Instantiate(prefab,new UnityEngine.Vector3(1000,0,1000),UnityEngine.Quaternion.identity).GetComponent<Tower>(); initialize.Invoke(tower,null);
 string name=tower.data.type.ToString();
 level.SetValue(tower,5);tower.GenerateShopItems();tower.CompleteShopPurchase(0,tower.myShopItems[0]);
