 rows.Add(new{test=name+" insufficient gold",passed=!tower.IsElementShop&&EconomyManager.Gold==0&&!ui.transitionConfirm.interactable});ui.CloseTransition();
 EconomyManager.Gold=gold;ui.OpenElementChange();ui.ConfirmTransition();
 rows.Add(new{test=name+" accept charges once and opens shop",passed=tower.IsElementShop&&EconomyManager.Gold==gold-tower.ElementChangeCost&&tower.Level==5&&!ui.transitionPanel.activeSelf});
