 ui.CloseTransition();rows.Add(new{test=name+" reject type keeps inventory",passed=tower.Backpack.Items.Count==2&&EconomyManager.Gold==gold});
 ui.OpenTowerTypeChange();ui.ChooseTransitionType((int)target.GetComponent<Tower>().data.type);ui.ConfirmTransition();var replacement=UİManager.activeTower;
